const ontologyText = $json.ontology_text || '';

//
// ======================================================
// EXTRAER ONTOLOGY TYPE
// ======================================================
//

const ontologyTypeMatch = ontologyText.match(
  /OntologyType:\s*([A-Za-z0-9_-]+)/i
);

const ontologyType = ontologyTypeMatch
  ? ontologyTypeMatch[1].trim().toLowerCase()
  : 'unknown';

//
// ======================================================
// NORMALIZACIÓN
// ======================================================
//

const normalized = ontologyText
  .replace(/\r\n/g, '\n')
  .trim();

//
// ======================================================
// UTILIDADES
// ======================================================
//

function extractSingleValue(block, fieldName) {

  const regex = new RegExp(
    `^${fieldName}:\\s*(.*)$`,
    'mi'
  );

  const match = block.match(regex);

  return match
    ? match[1].trim()
    : null;
}

function extractSectionList(block, sectionName) {

  const lines = block.split('\n');

  const values = [];

  let insideSection = false;

  for (const line of lines) {

    const trimmed = line.trim();

    //
    // Inicio de sección
    //
    if (
      trimmed.toLowerCase() ===
      `${sectionName.toLowerCase()}:`
    ) {
      insideSection = true;
      continue;
    }

    //
    // Cambio a otra sección
    //
    if (
      insideSection &&
      /^[a-zA-Z_]+:\s*/.test(trimmed)
    ) {
      break;
    }

    //
    // Item lista
    //
    if (
      insideSection &&
      trimmed.startsWith('- ')
    ) {
      values.push(
        trimmed.substring(2).trim()
      );
    }
  }

  return values;
}

function extractMultilineText(
  block,
  sectionName
) {

  const lines = block.split('\n');

  const values = [];

  let insideSection = false;

  for (const line of lines) {

    const trimmed = line.trim();

    if (
      trimmed.toLowerCase() ===
      `${sectionName.toLowerCase()}:`
    ) {
      insideSection = true;
      continue;
    }

    if (
      insideSection &&
      /^[a-zA-Z_]+:\s*/.test(trimmed)
    ) {
      break;
    }

    if (insideSection) {

      if (
        trimmed &&
        !trimmed.startsWith('- ')
      ) {
        values.push(trimmed);
      }
    }
  }

  return values.join(' ').trim();
}

//
// ======================================================
// DIVIDIR POR CONCEPTOS
// ======================================================
//

const rawSections = normalized.split(
  /^##\s+/gm
);

const concepts = [];

for (const section of rawSections) {

  let block = section.trim();

  if (!block) {
    continue;
  }

  //
  // Ignorar cabecera global
  //
  if (
    block.startsWith('# Home Insurance Ontology') ||
    block.includes('OntologyType:')
  ) {
    continue;
  }

  //
  // Ignorar bloques de figura ("## <figura>" con "imports:") --
  // se resuelven aparte, en "Merge Shared Texts Into Ramo"
  //
  if (
    /^imports:\s*\S/mi.test(block)
  ) {
    continue;
  }

  //
  // Limpieza
  //
  block = block
    .replace(/---+/g, '')
    .trim();

  const lines = block.split('\n');

  const conceptId =
    (lines[0] || '').trim();

  if (!conceptId) {
    continue;
  }

  //
  // ======================================================
  // EXTRAER CAMPOS
  // ======================================================
  //

  const riskField =
    extractSingleValue(
      block,
      'risk_field'
    );

  const context =
    extractSingleValue(
      block,
      'context'
    );

  const dataType =
    extractSingleValue(
      block,
      'data_type'
    );

  const meaning =
    extractSingleValue(
      block,
      'meaning'
    ) ||
    extractMultilineText(
      block,
      'meaning'
    );

  const interpretation =
    extractMultilineText(
      block,
      'interpretation'
    );

  const aliases =
    extractSectionList(
      block,
      'aliases'
    );

  const contractualExamples =
    extractSectionList(
      block,
      'contractual_examples'
    );

  const negativeAliases =
    extractSectionList(
      block,
      'negative_aliases'
    );

  //
  // ======================================================
  // TEXTO PARA EMBEDDINGS
  // ======================================================
  //

  const searchableParts = [

    ...(aliases || []),

    ...(contractualExamples || []),

    meaning || '',

    interpretation || ''

  ];

  const searchableText =
    searchableParts
      .filter(Boolean)
      .join('\n')
      .trim();

  //
  // Estadísticas
  //
  const wordCount =
    searchableText
      .split(/\s+/)
      .filter(Boolean)
      .length;

  concepts.push({
    json: {

      //
      // Identificación
      //
      concept_id: conceptId,
      concept_key:
        `${ontologyType}:${conceptId}`,
      ontology_type:
        ontologyType,

      //
      // Metadatos
      //
      risk_field:
        riskField,

      context:
        context,

      data_type:
        dataType,

      aliases,

      contractual_examples:
        contractualExamples,

      negative_aliases:
        negativeAliases,

      meaning,

      interpretation,

      //
      // Textos
      //
      ontology_raw:
        block,

      searchable_text:
        searchableText,

      //
      // Compatibilidad
      // (puedes mantenerlo
      // mientras migras)
      //
      ontology_text:
        searchableText,

      //
      // Métricas
      //
      concept_words:
        wordCount,

      concept_length:
        searchableText.length

    }
  });
}

//
// ======================================================
// ORDEN CONSISTENTE
// ======================================================
//

concepts.sort((a, b) =>
  a.json.concept_id.localeCompare(
    b.json.concept_id
  )
);

return concepts;

const splitter = $('Ontology Splitter').item.json;

const conceptId = splitter.concept_id;
const ontologyType = splitter.ontology_type;

const embedding = $json.embedding;

function deterministicId(str) {
  let hash = 0;

  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }

  return Math.abs(hash);
}

const conceptKey = `${ontologyType}:${conceptId}`;
const pointId = deterministicId(conceptKey);

return {
  json: {
    points: [
      {
        id: pointId,

        vector: embedding,

        payload: {

          // ==================================================
          // IDENTIFICACIÓN
          // ==================================================

          concept_key: conceptKey,
          concept_id: conceptId,
          ontology_type: ontologyType,

          // ==================================================
          // METADATOS ESTRUCTURADOS
          // ==================================================

          risk_field:
            splitter.risk_field || null,

          context:
            splitter.context || 'risk',

          data_type:
            splitter.data_type || null,

          aliases:
            splitter.aliases || [],

          contractual_examples:
            splitter.contractual_examples || [],

          negative_aliases:
            splitter.negative_aliases || [],

          meaning:
            splitter.meaning || null,

          interpretation:
            splitter.interpretation || null,

          // ==================================================
          // TEXTOS
          // ==================================================

          // Bloque completo original
          ontology_raw:
            splitter.ontology_raw || null,

          // Texto optimizado para embeddings
          searchable_text:
            splitter.searchable_text || null,

          // Texto exacto utilizado para generar el embedding
          embedding_source_text:
            splitter.searchable_text || null,

          // Compatibilidad con versiones anteriores
          ontology_text:
            splitter.searchable_text || null,

          // ==================================================
          // MÉTRICAS
          // ==================================================

          concept_words:
            splitter.concept_words || 0,

          concept_length:
            splitter.concept_length || 0
        }
      }
    ]
  }
};

const ontologyText = $json.ontology_text || '';

const match = ontologyText.match(/OntologyType:\s*([A-Za-z0-9_-]+)/i);
const ontologyType = match ? match[1].trim().toLowerCase() : 'unknown';

return {
  json: {
    ...$json,
    ontology_type: ontologyType
  }
};

const ontologyText = $json.ontology_text || '';

const match = ontologyText.match(/^Imports:\s*(.*)$/mi);

const imports = match
  ? match[1].split(',').map(s => s.trim()).filter(Boolean)
  : [];

return {
  json: {
    ...$json,
    imports
  }
};

const item = $input.first().json;
const imports = item.imports || [];

return imports.map(name => ({
  json: {
    import_name: name,
    file_path: `/home/node/ontologies/shared/${name}.md`,
    ramo_ontology_text: item.ontology_text,
    ramo_ontology_type: item.ontology_type
  }
}));

const sharedItems = $input.all();

if (sharedItems.length === 0) {
  throw new Error('Merge Shared Texts Into Ramo: no llego ningun item de import (imports declarados pero 0 ficheros leidos).');
}

// 'Read Shared Ontology File' sustituye el json del item por metadatos del
// fichero (mimeType, fileName...) y pierde los campos que veniamos
// arrastrando -- se recuperan referenciando el nodo origen por nombre en
// vez de fiarse del passthrough.
const originalItems = $('Prepare Import File Paths').all();

const ramoText = originalItems[0].json.ramo_ontology_text;
const ramoType = originalItems[0].json.ramo_ontology_type;

//
// ======================================================
// UTILIDADES (mismo patron que "Ontology Splitter")
// ======================================================
//

function extractSingleValue(block, fieldName) {
  const regex = new RegExp(`^${fieldName}:\\s*(.*)$`, 'mi');
  const match = block.match(regex);
  return match ? match[1].trim() : null;
}

function extractSectionList(block, sectionName) {
  const lines = block.split('\n');
  const values = [];
  let insideSection = false;
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.toLowerCase() === `${sectionName.toLowerCase()}:`) {
      insideSection = true;
      continue;
    }
    if (insideSection && /^[a-zA-Z_]+:\s*/.test(trimmed)) {
      break;
    }
    if (insideSection && trimmed.startsWith('- ')) {
      values.push(trimmed.substring(2).trim());
    }
  }
  return values;
}

function extractMultilineText(block, sectionName) {
  const lines = block.split('\n');
  const values = [];
  let insideSection = false;
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.toLowerCase() === `${sectionName.toLowerCase()}:`) {
      insideSection = true;
      continue;
    }
    if (insideSection && /^[a-zA-Z_]+:\s*/.test(trimmed)) {
      break;
    }
    if (insideSection) {
      if (trimmed && !trimmed.startsWith('- ')) {
        values.push(trimmed);
      }
    }
  }
  return values.join(' ').trim();
}

function splitConcepts(text) {
  const normalized = (text || '').replace(/\r\n/g, '\n').trim();
  const rawSections = normalized.split(/^##\s+/gm);
  const concepts = [];

  for (const section of rawSections) {
    let block = section.trim();
    if (!block) {
      continue;
    }
    if (block.includes('OntologyType:') || block.includes('SharedOntology:')) {
      continue;
    }
    block = block.replace(/---+/g, '').trim();

    const lines = block.split('\n');
    const conceptId = (lines[0] || '').trim();
    if (!conceptId) {
      continue;
    }

    concepts.push({
      concept_id: conceptId,
      field: extractSingleValue(block, 'field'),
      imports: extractSingleValue(block, 'imports'),
      data_type: extractSingleValue(block, 'data_type'),
      meaning: extractSingleValue(block, 'meaning') || extractMultilineText(block, 'meaning'),
      interpretation: extractMultilineText(block, 'interpretation'),
      aliases: extractSectionList(block, 'aliases'),
      contractual_examples: extractSectionList(block, 'contractual_examples'),
      negative_aliases: extractSectionList(block, 'negative_aliases')
    });
  }

  return concepts;
}

function capitalize(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

//
// ======================================================
// 1. CONCEPTOS DE CADA FICHERO COMPARTIDO IMPORTADO
// ======================================================
//

const sharedFieldsByImportName = {};

sharedItems.forEach((item, idx) => {
  const importName = (originalItems[idx] && originalItems[idx].json.import_name) || `import#${idx}`;
  sharedFieldsByImportName[importName] = splitConcepts(item.json.shared_text || '');
});

//
// ======================================================
// 2. BLOQUES DE FIGURA DEL RAMO ("## <figura>" con "imports:")
// ======================================================
//

const ramoConcepts = splitConcepts(ramoText);
const figuraBlocks = ramoConcepts.filter((c) => c.imports);

if (figuraBlocks.length === 0) {
  throw new Error('Merge Shared Texts Into Ramo: se declararon imports en la cabecera pero no se encontro ningun bloque de figura (## <figura> con "imports:") en el ramo.');
}

//
// ======================================================
// 3. PRODUCTO CRUZADO: FIGURA x CAMPO
// ======================================================
//

const HOLDER_CONTAINER = 'holder';
const generated = [];

for (const figuraBlock of figuraBlocks) {
  const figuraName = figuraBlock.concept_id;
  const importName = figuraBlock.imports;
  const sharedFields = sharedFieldsByImportName[importName];

  if (!sharedFields) {
    throw new Error(`Figura '${figuraName}' importa '${importName}', pero ese import no esta disponible (revisar Imports: en la cabecera del ramo).`);
  }

  for (const sharedField of sharedFields) {
    const fieldName = sharedField.field || sharedField.concept_id;
    const conceptId = `${figuraName}${capitalize(fieldName)}`;
    const isHolder = figuraName === HOLDER_CONTAINER;
    const riskField = isHolder ? fieldName : `${figuraName}.${fieldName}`;
    const context = isHolder ? 'holder' : 'risk';

    // Bug real (27/08, Divina Seguros): los alias de la FIGURA
    // ("propietario", "tomador", "conductor habitual") identifican QUIEN
    // protagoniza el texto, no el SIGNIFICADO de cada campo importado --
    // mezclarlos en "aliases" hacia que, p.ej., la sola mencion de
    // "tomador" activara como candidato "ocupacion"/"situacion laboral"
    // del tomador sin que el texto hablara de empleo en absoluto (visto
    // en produccion: crmEmploymentStatus vía matched_aliases=['tomador']
    // para un texto sobre quien conduce el vehiculo). Se separan: los
    // alias de figura solo enriquecen el texto de embedding (señal
    // blanda, sujeta al umbral de score), nunca el array "aliases" que
    // "Ontology Relevance Filter" usa para el match literal duro.
    const aliases = Array.from(new Set(sharedField.aliases || []));
    const figureAliases = Array.from(new Set(figuraBlock.aliases || []));
    const contractualExamples = Array.from(new Set([...(sharedField.contractual_examples || []), ...(figuraBlock.contractual_examples || [])]));
    const negativeAliases = Array.from(new Set([...(sharedField.negative_aliases || []), ...(figuraBlock.negative_aliases || [])]));

    const meaning = sharedField.meaning;
    const interpretation = sharedField.interpretation;

    const searchableParts = [
      ...aliases,
      ...figureAliases,
      ...contractualExamples,
      meaning || '',
      interpretation || ''
    ];

    const searchableText = searchableParts.filter(Boolean).join('\n').trim();
    const wordCount = searchableText.split(/\s+/).filter(Boolean).length;

    generated.push({
      json: {
        concept_id: conceptId,
        concept_key: `${ramoType}:${conceptId}`,
        ontology_type: ramoType,
        risk_field: riskField,
        context,
        data_type: sharedField.data_type,
        aliases,
        contractual_examples: contractualExamples,
        negative_aliases: negativeAliases,
        meaning,
        interpretation,
        ontology_raw: `[generado] figura '${figuraName}' + campo '${fieldName}' de '${importName}'`,
        searchable_text: searchableText,
        ontology_text: searchableText,
        concept_words: wordCount,
        concept_length: searchableText.length
      }
    });
  }
}

return generated;

const splitter = $('Merge Shared Texts Into Ramo').item.json;

const conceptId = splitter.concept_id;
const ontologyType = splitter.ontology_type;

const embedding = $json.embedding;

function deterministicId(str) {
  let hash = 0;

  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }

  return Math.abs(hash);
}

const conceptKey = `${ontologyType}:${conceptId}`;
const pointId = deterministicId(conceptKey);

return {
  json: {
    points: [
      {
        id: pointId,

        vector: embedding,

        payload: {

          concept_key: conceptKey,
          concept_id: conceptId,
          ontology_type: ontologyType,

          risk_field:
            splitter.risk_field || null,

          context:
            splitter.context || 'risk',

          data_type:
            splitter.data_type || null,

          aliases:
            splitter.aliases || [],

          contractual_examples:
            splitter.contractual_examples || [],

          negative_aliases:
            splitter.negative_aliases || [],

          meaning:
            splitter.meaning || null,

          interpretation:
            splitter.interpretation || null,

          ontology_raw:
            splitter.ontology_raw || null,

          searchable_text:
            splitter.searchable_text || null,

          embedding_source_text:
            splitter.searchable_text || null,

          ontology_text:
            splitter.searchable_text || null,

          concept_words:
            splitter.concept_words || 0,

          concept_length:
            splitter.concept_length || 0
        }
      }
    ]
  }
};
